insert into public.site_settings (id, data) values (1, '{"site_name": "KTM EduTech", "owner_name": "Kyd Tantano Masong", "tagline": "Education Meets Innovation", "logo_url": "https://ik.imagekit.io/ktmedutech/KTM%20EduTech%20Images/ktm-logo%20gs.png?updatedAt=1790877702360", "logo_alt": "KTM EduTech", "logo_on_navy_badge": true, "favicon_url": "https://ik.imagekit.io/ktmedutech/KTM%20EduTech%20Images/ktm-logo.png?updatedAt=1776505502099", "brand_navy": "#232450", "brand_gold": "#FEDC69", "font_family": "Poppins", "default_theme": "light", "header_cta_label": "Contact", "header_cta_url": "/contact-us", "footer_description": "Bridging education and technology through innovative web solutions and curriculum design. KTM EduTech by Kyd Tantano Masong is dedicated to creating impactful digital experiences, practical educational resources, and modern web solutions for a connected world.", "footer_tagline": "Designed with passion for education and technology", "copyright": "© 2026 KTM EduTech | Kyd Tantano Masong. All rights reserved.", "email": "contact@kydmasong.net", "availability": "Available for remote collaboration, locally and internationally.", "primary_location_label": "Samut Prakan, Thailand", "primary_location_lat": 13.6677, "primary_location_lng": 100.6506, "map_query": "KTM EduTech by Kyd Tantano Masong", "current_location_label": "Koh Samui, Surat Thani, Thailand", "social": [{"platform": "GitHub", "url": "https://github.com/KTM-EduTech"}, {"platform": "LinkedIn", "url": "https://www.linkedin.com/in/ktmedutech/"}, {"platform": "YouTube", "url": "https://www.youtube.com/@KTMEduTech"}, {"platform": "Facebook", "url": "https://www.facebook.com/KTMEduTech/"}], "seo_title_template": "%s | KTM EduTech", "seo_default_title": "KTM EduTech | Kyd Tantano Masong", "seo_default_description": "Experienced Computer Science Teacher and Full-Stack Web Developer with a background in educational technology and software development.", "seo_og_image_url": "", "blog_enabled": false, "enquiry_types": ["Web development", "Educational platforms", "ICT training", "EdTech tools", "Consultation or collaboration", "Other"], "privacy_policy_url": "https://legalframeworks.ktm-edutech.net"}'::jsonb);
