insert into public.page_sections (page_id, type, label, data, position, visible, needs_review, review_note) values ('5f4a7108-8428-56b6-9d85-813622425b0b', 'intro_split', NULL, '{"eyebrow": "About me", "heading": "Hello, I''m Kyd", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Based in Samut Prakan and currently working from Koh Samui, Surat Thani, Kyd is a Computer Science Teacher and Full-Stack Web Developer with over two decades of lesson planning and digital resource development. His work spans EdTech portals such as ICT Click Digital Media, AI tools, and creative coding with Scratch."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Available for remote collaboration, locally and internationally."}]}]}, "focus_areas": ["EdTech Integration", "Curriculum Design"], "image_id": "2288cde2-304d-5ebc-9cd1-a767fbe6d0f1", "link_label": "Learn more about my journey", "link_url": "/about"}'::jsonb, 2, true, true, 'Captured as a summary of the original page. Replace with your exact wording or approve.');
