insert into public.pages (id, title, slug, status, seo_title, seo_description, needs_review, review_note, sort_order, published_at) values ('e090c8f6-e093-5283-8d5b-a188321e3a58', 'About', 'about', 'published', 'About', 'Kyd Tantano Masong: educator and full-stack web developer with over two decades of classroom teaching, educational leadership and web development.', false, NULL, 1, now());
insert into public.page_sections (page_id, type, label, data, position, visible, needs_review, review_note) values ('e090c8f6-e093-5283-8d5b-a188321e3a58', 'page_header', NULL, '{"eyebrow": "My Story & Vision", "heading": "Educator by Heart, Developer by Craft", "intro": "Over two decades of classroom teaching, educational leadership and full-stack web development, building digital tools for meaningful learning.", "tags": ["Educator", "Web Developer", "EdTech Architect"], "image_id": "2288cde2-304d-5ebc-9cd1-a767fbe6d0f1"}'::jsonb, 0, true, true, 'Captured as a summary of the original page. Replace with your exact wording or approve. (introduction)');
insert into public.page_sections (page_id, type, label, data, position, visible, needs_review, review_note) values ('e090c8f6-e093-5283-8d5b-a188321e3a58', 'timeline', NULL, '{"eyebrow": "My journey", "heading": "From the classroom to the codebase", "items": [{"year": "2002", "title": "Starting out", "body": "Began collecting and curating websites and interactive resources for educators and students, after seeing that useful developer tools were not always easy for teachers and learners to access or understand."}, {"year": "2004", "title": "Building the hub", "body": "Joined Assumption College Samutprakarn as a computer teacher in May 2004 and launched www.ict-click.com for students. Educators worldwide began visiting."}, {"year": "2016", "title": "A new name", "body": "Rebranded as ICT Click Digital Media and moved the domain from .com to .net.", "link_label": "ICT Click Digital Media", "link_url": "https://www.ictclickdigitalmedia.net/"}, {"year": "2019", "title": "Responding to COVID-19", "body": "As schools moved to remote learning, expanded ICT Click Digital Media with two portals: one for educators and one for learners, named to be memorable for young learners from Kindergarten 3.", "link_label": "ICDM Learners portal", "link_url": "https://icdm-student-portal.blogspot.com/"}, {"year": "2023", "title": "Expanding horizons", "body": "Began creating original interactive tools with HTML5, CSS, PHP, JavaScript, H5P, Nearpod, LearningApps, Scratch and more."}]}'::jsonb, 1, true, true, 'Captured as a summary of the original page. Replace with your exact wording or approve. 2002 and 2004 entries follow the confirmed May 2004 start at Assumption.');
insert into public.page_sections (page_id, type, label, data, position, visible, needs_review, review_note) values ('e090c8f6-e093-5283-8d5b-a188321e3a58', 'quote', NULL, '{"text": "My lifelong mission is to inspire the next generation of tech enthusiasts and to bridge technology and education.", "attribution": "Kyd Tantano Masong"}'::jsonb, 2, true, true, 'Captured as a summary of the original page. Replace with your exact wording or approve.');
