insert into public.page_sections (page_id, type, label, data, position, visible, needs_review, review_note) values ('7c6096c4-8227-5650-8915-4682836dbec5', 'page_header', NULL, '{"eyebrow": "Our Purpose", "heading": "I Believe Learning Should Inspire", "intro": "Combining a passion for education and technology to build interactive tools and learning experiences that help educators and inspire students to explore and grow."}'::jsonb, 0, true, true, 'Captured as a summary of the original page. Replace with your exact wording or approve.');
insert into public.page_sections (page_id, type, label, data, position, visible, needs_review, review_note) values ('7c6096c4-8227-5650-8915-4682836dbec5', 'cards', NULL, '{"eyebrow": "Mission & Vision", "heading": "My mission is simple yet profound", "items": [{"kicker": "Mission", "title": "Tools that empower", "body": "Provide cutting-edge educational tools and resources, equip educators with innovative solutions, and help students reach their full potential, so the classroom becomes a dynamic space for discovery and achievement."}, {"kicker": "Vision", "title": "Learning for everyone", "body": "Use new technology to make learning interactive and engaging for everyone, and make educational technology accessible to every student regardless of location or background, adapting to current trends and anticipating future needs."}]}'::jsonb, 1, true, true, 'Captured as a summary of the original page. Replace with your exact wording or approve. Card titles are new; edit as needed.');
