insert into public.experiences (role, organization, organization_url, location, start_label, end_label, sort_date, summary, bullets, links, status, needs_review, review_note, sort_order) values ('EdTech Designer-Developer', 'Panyadee British International School of Samui (PBISS)', 'https://pbiss.ac.th/', 'Surat Thani, Thailand', NULL, 'Present', NULL, 'Designing and developing custom digital solutions for school operations, student engagement and classroom interactivity, using full-stack development and user-centred design.', ARRAY['PBISS Student Collection System: a digital application for managing student collection and dismissal procedures.','PBISS House Point System: a digital house-points management application supporting house-point tracking across year groups.','KTM EduTech C-Spinner: an interactive random wheel tool for classroom activities and student selection.']::text[], '[{"label": "Student Collection System", "url": "https://pbiss-picksys.ktm-edutech.net/"}, {"label": "House Point System", "url": "https://hps.ktm-edutech.net/"}, {"label": "C-Spinner", "url": "https://ws.ktm-edutech.net/"}]'::jsonb, 'draft', true, 'Start date to confirm: the old site says Jan 2025, which overlaps Trinity (Feb–Jul 2025). Add the date, then publish.', 0);
insert into public.experiences (role, organization, organization_url, location, start_label, end_label, sort_date, summary, bullets, links, status, needs_review, review_note, sort_order) values ('Computer Science and ICT Teacher', 'Panyadee British International School of Samui (PBISS)', 'https://pbiss.ac.th/', 'Surat Thani, Thailand', 'Sep 2025', 'Present', '2025-09-01', NULL, ARRAY['Teaching Computer Science aligned with the Cambridge Primary Curriculum (Key Stage 2), covering digital literacy, computational thinking and responsible online behaviour.','Designing interactive, student-centred lessons covering coding, keyboarding, mouse skills and multimedia to build ICT foundations.']::text[], '[]'::jsonb, 'draft', true, 'Confirm the start month (Sep 2025 on the old site). Captured as a summary of the original page. Replace with your exact wording or approve.', 1);
insert into public.experiences (role, organization, organization_url, location, start_label, end_label, sort_date, summary, bullets, links, status, needs_review, review_note, sort_order) values ('Art Teacher & Computer Science Teacher', 'Trinity International School', 'https://trinity.ac.th/', 'Bangkok, Thailand', 'Feb 2025', 'Jul 2025', '2025-02-01', NULL, ARRAY['Taught Art (Middle and High School) under the American Curriculum, focusing on creativity, critical thinking and visual literacy.','Taught Early Years Computer Science (K3–Grade 3), introducing digital literacy and foundational coding through age-appropriate activities aligned with iMAP goals.','Designed blended hands-on and digital lessons that encourage exploration and collaboration.']::text[], '[]'::jsonb, 'published', true, 'Captured as a summary of the original page. Replace with your exact wording or approve.', 2);
insert into public.experiences (role, organization, organization_url, location, start_label, end_label, sort_date, summary, bullets, links, status, needs_review, review_note, sort_order) values ('Computer Science Educator [K-6]', 'Anglo Singapore International School – Campus 31', 'https://anglosingapore.ac.th/31/', 'Bangkok, Thailand', 'Jul 2017', 'Aug 2024', '2017-07-01', NULL, ARRAY['Designed and implemented a K–6 Computer Science curriculum (algorithms, coding, digital systems) aligned with IGCSE and A Level standards.','Delivered lessons that combined theory with hands-on activities.','Led after-school technology clubs for project-based learning.']::text[], '[]'::jsonb, 'published', true, 'Captured as a summary of the original page. Replace with your exact wording or approve.', 3);
